mapper.select:
SELECT id, name, config, enabled, revision, create_time, update_time FROM ifj_mail_channel
LOWER(name) LIKE LOWER(#{namePattern}) AND enabled = #{enabled}
ORDER BY update_time DESC, id DESC

mapper.update:
UPDATE ifj_mail_channel SET name = #{name}, config = #{config}, enabled = #{enabled},
    revision = revision + 1, update_time = #{updateTime}
WHERE id = #{id} AND revision = #{revision}

mapper.delete:
DELETE FROM ifj_mail_channel
WHERE id IN #{id}
WHERE 1 = 0
